function lyr2024(B){/* ASK 363 (K-LYR; plan Wall 7616; reads W1 7618, W2 7619): on each judge's final text, every RESULT and KEYSTONE line is read for the verses read together through the layers (Commitment 13; Isaiah 28:10; single verse doctrine is prohibited): (a) an [L1] with its reference; (b) an [L3] whose reference is not one of the line's [L1]; (c) an [L4] step, on a line that holds both (a) and (b); (d) every [L3] reference stands in the GROUND of a collision line the verdict line names. TRIAL, record only: an AUDIT v59 line; no send-back call; it counts nothing, removes no seat and moves no grade (Rulings 383, 428). */
if(!Array.isArray(B))return null;let ch=0;const REF='((?:[1-3] )?[A-Z][a-z]+(?: of [A-Z][a-z]+)? \\d{1,3}:\\d{1,3})';
const tags=(l,n)=>{const o=[];const re=new RegExp('[\\[(]L'+n+'[\\])]\\s*'+REF,'g');let m;while((m=re.exec(l)))o.push(m[1].replace(/\s+/g,' '));return [...new Set(o)];};const has=(l,n)=>new RegExp('[\\[(]L'+n+'[\\])]').test(l);
const RES=/^[\s>-]*RESULT\s*:\s*(?!CURED\b|UNCURED\b)/i,KEY=/^[\s>-]*KEYSTONE\s*:\s*(D\d+)\b/i,DERIVED=/derived by the engine|derived after the send-back|\brecomputed\b|BROKEN BY A CONFIRMED CLOSING CONTRADICTION/i,COL=/^[\s>-]*(?:\d+[.)]\s*)?(D\d+)\s+vs\.?\s+(C\d+)\b/i;
const o=B.map(s=>{let b;try{b=JSON.parse(s);}catch(e){return s;}const p=b.payload||{};const raw=String(p.verdict_raw||'');if(!p.judge_seat||raw.includes('[AUDIT v59:'))return s;
 const L=raw.replace(/\\n/g,'\n').replace(/\\+"/g,'"').replace(/[*_`]+/g,'').split('\n').map(x=>x.trim()).filter(x=>x&&!/^\[(?:AUDIT|EXTRACTOR)\b/.test(x)); const G={};for(const l of L){const m=l.match(COL);const gi=l.search(/GROUND\s*:/i);if(!m||gi<0)continue;const k=(m[1]+' VS '+m[2]).toUpperCase();G[k]=(G[k]||'')+' '+l.slice(gi).replace(/\s+/g,' ');} const rec=[];for(const l of L){if(DERIVED.test(l))continue;const k=l.match(KEY);if(!k&&!RES.test(l))continue;if(k&&/^[\s>-]*KEYSTONE\s*:\s*D\d+\s*(?:--|—|-|:)?\s*WITHDRAWN\b/i.test(l))continue;  const a=tags(l,1),c3=tags(l,3).filter(r=>!a.includes(r)),f=[];  if(!a.length)f.push('(a) no [L1] with its reference');if(!c3.length)f.push('(b) no [L3] with a reference other than its [L1]');  if(!has(l,4))f.push('(c) no [L4] step');else if(!a.length||!c3.length)f.push('(c) its [L4] stands on a line without both an [L1] and an [L3]');  const labs=[...new Set([...l.matchAll(/\b(D\d+)\s+vs\.?\s+(C\d+)\b/gi)].map(m=>(m[1]+' VS '+m[2]).toUpperCase()))];const gr=labs.map(x=>G[x]||'').join(' ');  if(!labs.length)f.push('(d) names no collision line to read its [L3] against');else{const hasRef=(g,r)=>new RegExp('(?:^|[^A-Za-z0-9])'+r.replace(/[.*+?^$(){}|[\]\\]/g,'\\$&').replace(/ /g,'\\s+')+'(?![0-9]|:\\d)').test(g);const miss=c3.filter(r=>!hasRef(gr,r)); /* rev 2 (W1 7623): the whole reference, so Romans 1:3 does not match Romans 1:30 */if(miss.length)f.push('(d) [L3] '+miss.join(', ')+' stands in no GROUND of '+labs.join(', '));if(!/[\[(]L3[\])]/.test(gr))f.push('the GROUNDs of '+labs.join(', ')+' name no [L3]');}  if(f.length)rec.push((k?'KEYSTONE '+k[1].toUpperCase():'RESULT')+': '+f.join('; '));} const U=[...new Set(rec)];if(!U.length)return s;p.verdict_raw=raw+U.map(x=>'\n[AUDIT v59: LAYERS READ TOGETHER (K-LYR, ASK 363, TRIAL) -- SEAT: '+p.judge_seat+'; LINE: '+x+'; record-only, not counted in drv_uncured; it removes no seat and moves no grade]').join('');ch++;return JSON.stringify(b);});return ch?o:null;}